const sid = (key: string) => "products-lesson-" + key;
const tid = (key: string) => "products-term-" + key;
const lid = (chapter: string, part: number) => "products-" + chapter + "-" + part;
function source(key: string, title: string, author: string, organization: string, published: string, url: string, passage: string, access: HistorySource["access"], limitation: string): HistorySource {
  return { id: sid(key), title, author, organization, published, url, passage, access, limitation, verifiedAt: "2026-11-12", documentKind: access === "excerpt" ? "Passages originaux consultés" : "Publication originale ou page de son organisme émetteur" };
}
